# worker/job_processor.py - Background job worker for Solidity contract deployment
import unicodedata
import hashlib
import re
import json
import os
from typing import Dict, Optional, Tuple

# Feature flags loaded from environment
FEATURE_FLAGS = {
    "unicode_normalization": os.environ.get("FF_UNICODE_NORM", "NFC"),
    "strict_identifier_check": os.environ.get("FF_STRICT_ID", "true"),
    "allow_extended_chars": os.environ.get("FF_EXTENDED_CHARS", "false"),
    "deployment_mode": os.environ.get("FF_DEPLOY_MODE", "mainnet"),
}

class ContractIdentifierRegistry:
    """Registry that maps normalized contract identifiers to deployment addresses."""

    def __init__(self):
        self._registry: Dict[str, str] = {}
        self._permissions: Dict[str, str] = {}  # identifier -> owner
        self._audit_log = []

    def _normalize_identifier(self, identifier: str) -> str:
        """Normalize contract identifier using configured Unicode normalization form."""
        norm_form = FEATURE_FLAGS["unicode_normalization"]
        # Apply normalization
        normalized = unicodedata.normalize(norm_form, identifier)

        if FEATURE_FLAGS["strict_identifier_check"] == "true":
            # Strip characters outside basic identifier set after normalization
            # But we check BEFORE normalization for the allow list
            if FEATURE_FLAGS["allow_extended_chars"] == "false":
                # Only allow ASCII alphanumeric, underscore, dot
                filtered = ""
                for ch in normalized:
                    if ch.isascii() and (ch.isalnum() or ch in "_."):
                        filtered += ch
                normalized = filtered

        return normalized

    def _compute_registry_key(self, identifier: str) -> str:
        """Compute the registry lookup key from a normalized identifier."""
        # Use NFKC for the registry key computation to collapse compatibility equivalents
        registry_normalized = unicodedata.normalize("NFKC", identifier)
        return hashlib.sha256(registry_normalized.encode("utf-8")).hexdigest()[:16]

    def register_contract(self, identifier: str, address: str, owner: str) -> Tuple[bool, str]:
        """Register a contract identifier to a deployment address."""
        normalized = self._normalize_identifier(identifier)

        if not normalized:
            return False, "Invalid identifier after normalization"

        registry_key = self._compute_registry_key(normalized)

        if registry_key in self._registry:
            existing_owner = self._permissions.get(registry_key, "")
            if existing_owner != owner:
                return False, f"Identifier already registered by another owner"
            # Same owner can update

        self._registry[registry_key] = address
        self._permissions[registry_key] = owner
        self._audit_log.append({
            "action": "register",
            "identifier": normalized,
            "key": registry_key,
            "address": address,
            "owner": owner
        })
        return True, registry_key

    def resolve_contract(self, identifier: str) -> Optional[str]:
        """Resolve a contract identifier to its deployment address."""
        normalized = self._normalize_identifier(identifier)
        registry_key = self._compute_registry_key(normalized)
        return self._registry.get(registry_key)

    def check_ownership(self, identifier: str, claimed_owner: str) -> bool:
        """Check if the claimed owner owns the given identifier."""
        normalized = self._normalize_identifier(identifier)
        registry_key = self._compute_registry_key(normalized)
        return self._permissions.get(registry_key) == claimed_owner


class DeploymentJobWorker:
    """Background worker that processes Solidity contract deployment jobs."""

    def __init__(self, registry: ContractIdentifierRegistry):
        self.registry = registry
        self._job_queue = []

    def _validate_solidity_source(self, source: str) -> bool:
        """Basic validation of Solidity source code."""
        if not source or len(source) > 100000:
            return False
        if "pragma solidity" not in source:
            return False
        return True

    def _extract_contract_name(self, source: str) -> Optional[str]:
        """Extract the main contract name from Solidity source."""
        match = re.search(r'contract\s+(\w+)', source)
        if match:
            return match.group(1)
        return None

    def submit_deployment_job(self, job: dict) -> Tuple[bool, str]:
        """Submit a deployment job to the worker queue."""
        required_fields = ["source", "identifier", "owner", "network"]
        for field in required_fields:
            if field not in job:
                return False, f"Missing required field: {field}"

        if not self._validate_solidity_source(job["source"]):
            return False, "Invalid Solidity source"

        # Validate the identifier matches the contract name
        contract_name = self._extract_contract_name(job["source"])

        # Normalize both for comparison
        norm_identifier = self.registry._normalize_identifier(job["identifier"])
        norm_contract = self.registry._normalize_identifier(contract_name) if contract_name else ""

        # The identifier must contain the contract name as a component
        if norm_contract and norm_contract not in norm_identifier:
            return False, "Identifier must reference the contract name"

        self._job_queue.append(job)
        return True, "Job queued successfully"

    def process_next_job(self) -> Optional[dict]:
        """Process the next job in the queue."""
        if not self._job_queue:
            return None

        job = self._job_queue.pop(0)

        # Simulate deployment - in production this would compile and deploy
        simulated_address = "0x" + hashlib.sha256(
            job["source"].encode("utf-8")
        ).hexdigest()[:40]

        # Register the contract
        success, result = self.registry.register_contract(
            job["identifier"],
            simulated_address,
            job["owner"]
        )

        return {
            "success": success,
            "result": result,
            "address": simulated_address if success else None,
            "identifier": job["identifier"],
            "owner": job["owner"]
        }


def create_worker() -> DeploymentJobWorker:
    """Factory function to create a configured worker instance."""
    registry = ContractIdentifierRegistry()
    return DeploymentJobWorker(registry)
